import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen0Test {

    private static final double EPSILON = 1e-10;















    @Test
    public void testDivide_Branch_AbsC_LessThan_AbsD() {
        // divisor.getReal() = 1, divisor.getImaginary() = 10
        // |1| < |10| is true
        Complex c = new Complex(2.0, 4.0);
        Complex divisor = new Complex(1.0, 10.0);

        // (2+4i) / (1+10i) = [(2+4i)(1-10i)] / [1^2 + 10^2]
        // = [2 - 20i + 4i - 40i^2] / 101
        // = [2 + 40 + (4-20)i] / 101 = 42/101 - 16/101i
        Complex result = c.divide(divisor);

        assertEquals(42.0 / 101.0, result.getReal(), EPSILON);
        assertEquals(-16.0 / 101.0, result.getImaginary(), EPSILON);
    }




}

