public class Complex_divide_TriageGen0Test {

    private static final double EPSILON = 1e-10;

















    @Test
    public void testDivide_Branch_AbsC_GreaterThan_AbsD() {
        // divisor.getReal() = 10, divisor.getImaginary() = 1
        // |10| < |1| is false
        Complex c = new Complex(2.0, 4.0);
        Complex divisor = new Complex(10.0, 1.0);

        // (2+4i) / (10+1i) = [(2+4i)(10-i)] / [10^2 + 1^2]
        // = [20 - 2i + 40i - 4i^2] / 101
        // = [20 + 4 + (40-2)i] / 101 = 24/101 + 38/101i
        Complex result = c.divide(divisor);

        assertEquals(24.0 / 101.0, result.getReal(), EPSILON);
        assertEquals(38.0 / 101.0, result.getImaginary(), EPSILON);
    }


}

